import generalMixin from "../../mixins/general";

export default {
  name: "TrainingPlanReview",
  mixins: [generalMixin, processQuestionnaire],
  props: ["queries"],
  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/ihris-ps-training-plan-review",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/ps-training-plan-review-profile",
      isEdit: true,
      overlay: false,
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      valid: false,
      submitting: false,
      loadingRequest: true,

      accessChecked: false,
      isPS: false,

      // Confirmation dialog
      confirmDialog: false,
      confirmDialogTitle: "",
      confirmDialogMessage: "",
      confirmDialogIcon: { icon: "", color: "" },
      reviewDate: new Date().toISOString().split("T")[0],

      // Request data
      requestData: {
        id: "",
        practitionerId: "",
        trainingNeedId: "",
        trainingType: "",
        trainingTypeDisplay: "",
        duration: "",
        methodology: "",
        methodologyDisplay: "",
        course: "",
        qualificationLevel: "",
        institution: "",
        comments: "",
        status: "",
        statusDisplay: "",
        submissionDate: "",
      },
      editReview: false,
      hodReview: {
        status: {},
        date: "",
        comments: "",
      },
      supervisorReview: {
        status: {},
        date: "",
        comments: "",
      },
      hrReview: {
        status: {},
        date: "",
        comments: "",
      },
      psReview: {
        status: {},
        date: "",
        comments: "",
      },

      // Additional data
      practitionerName: "",
      trainingNeedTitle: "",
      trainingNeedDescription: "",
    };
  },

  computed: {
    requestId() {
      return this.queries?.request || this.$route.query.request;
    },

    practitionerId() {
      return this.queries?.practitioner || this.$route.query.practitioner;
    },

    isAlreadyReviewed() {
      return (
        this.requestData.status && this.requestData.status !== "underpsreview"
      );
    },
    canEdit() {
      return false;
    },
  },

  methods: {
    async checkAccess() {
      try {
        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch("/site/general/getPS");
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const ps = await resp.json();

        this.isPS =
          !!ps.practitioner &&
          String(ps.practitioner) === String(practitionerId);
      } catch (err) {
        console.error("checkAccess error:", err);
        this.isPS = false;
      } finally {
        this.accessChecked = true;
      }
    },

    async getReviews() {
      try {
        const response = await fetch(
          `/fhir/Basic?trainplanrequest=Basic/${this.requestId}&_profile=http://ihris.org/fhir/StructureDefinition/supervisor-training-plan-review-profile,http://ihris.org/fhir/StructureDefinition/hod-training-plan-review-profile,http://ihris.org/fhir/StructureDefinition/hr-training-plan-review-profile,http://ihris.org/fhir/StructureDefinition/ps-training-plan-review-profile`,
        );
        const result = await response.json();
        if (result.entry) {
          result.entry.forEach((entry) => {
            const resource = entry.resource;
            const profile = resource.meta?.profile?.[0];
            const reviewData = {
              status: resource.extension?.find(
                (ext) =>
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/review-status",
              )?.valueCoding,
              date: resource.extension?.find(
                (ext) =>
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/event-date",
              )?.valueDate,
              comments: resource.extension?.find(
                (ext) =>
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/comments",
              )?.valueString,
            };
            if (profile) {
              if (profile.includes("supervisor-training-plan-review-profile")) {
                this.supervisorReview = reviewData;
              } else if (profile.includes("hod-training-plan-review-profile")) {
                this.hodReview = reviewData;
              } else if (profile.includes("hr-training-plan-review-profile")) {
                this.hrReview = reviewData;
              } else if (profile.includes("ps-training-plan-review-profile")) {
                this.fhirId = resource.id;
                this.psReview = reviewData;
              }
            }
          });
        }
      } catch (error) {
        console.error("Error fetching other reviews:", error);
      }
    },
    async loadRequestData() {
      this.loadingRequest = true;
      try {
        if (!this.requestId) {
          this.showSnackbar("No request ID provided", "error");
          this.loadingRequest = false;
          return;
        }

        // Fetch the training plan request
        const response = await fetch(`/fhir/Basic/${this.requestId}`);
        const request = await response.json();

        // Extract training need reference
        const needExt = request.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/training-need-reference",
        );
        if (needExt && needExt.valueReference) {
          this.requestData.trainingNeedId = needExt.valueReference.reference.split(
            "/",
          )[1];
          await this.loadTrainingNeed(this.requestData.trainingNeedId);
        }

        // Extract training type
        const typeExt = request.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/training-type",
        );
        if (typeExt && typeExt.valueCoding) {
          this.requestData.trainingType = typeExt.valueCoding.code;
          this.requestData.trainingTypeDisplay = typeExt.valueCoding.display;
        }

        // Extract duration
        const durationExt = request.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/duration",
        );
        if (durationExt) {
          this.requestData.duration = durationExt.valueInteger;
        }

        // Extract methodology
        const methodExt = request.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/learning-methodology",
        );
        if (methodExt && methodExt.valueCoding) {
          this.requestData.methodology = methodExt.valueCoding.code;
          this.requestData.methodologyDisplay = methodExt.valueCoding.display;
        }

        // Extract course (new multi-field logic with backward compat)
        const qualNameExt = request.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
        );
        this.requestData.course = qualNameExt.valueString;
        const qualLevelExt = request.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/qualification-level",
        );
        this.requestData.qualificationLevel =
          qualLevelExt?.valueCoding?.display ||
          qualLevelExt?.valueCoding?.code ||
          "";

        // Extract institution
        const instExt = request.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/planning-institution",
        );
        if (instExt) {
          this.requestData.institution = instExt.valueString;
        }

        // Extract comments
        const commentsExt = request.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/comments",
        );
        if (commentsExt) {
          this.requestData.comments = commentsExt.valueString;
        }

        // Extract status
        const statusExt = request.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/request-status",
        );
        if (statusExt && statusExt.valueCoding) {
          this.requestData.status = statusExt.valueCoding.code;
          this.requestData.statusDisplay = statusExt.valueCoding.display;
        }

        // Extract submission date
        const dateExt = request.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/event-date",
        );
        if (dateExt) {
          this.requestData.submissionDate = dateExt.valueDate;
        }

        // Extract practitioner
        const practExt = request.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
        );
        if (practExt && practExt.valueReference) {
          this.requestData.practitionerId = practExt.valueReference.reference.split(
            "/",
          )[1];
          await this.loadPractitioner(this.requestData.practitionerId);
        }

        this.requestData.id = request.id;
      } catch (error) {
        console.error("Error loading request data:", error);
        this.showSnackbar("Error loading request data", "error");
      } finally {
        this.loadingRequest = false;
      }
    },

    async loadPractitioner(practitionerId) {
      try {
        const response = await fetch(
          `/fhir/Practitioner/${practitionerId}?_elements=name`,
        );
        const practitioner = await response.json();
        if (practitioner.name && practitioner.name.length > 0) {
          const name = practitioner.name[practitioner.name.length - 1];
          this.practitionerName = `${
            name.given ? name.given.join(" ") : ""
          } ${name.family || ""}`.trim();
        }
      } catch (error) {
        console.error("Error loading practitioner:", error);
      }
    },

    async loadTrainingNeed(needId) {
      try {
        const response = await fetch(`/fhir/Basic/${needId}`);
        const need = await response.json();

        const nameExt = need.extension.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
        );
        if (nameExt) {
          this.trainingNeedTitle = nameExt.valueString;
        }

        const descExt = need.extension.find(
          (ext) =>
            ext.url === "http://ihris.org/fhir/StructureDefinition/description",
        );
        if (descExt) {
          this.trainingNeedDescription = descExt.valueString;
        }
      } catch (error) {
        console.error("Error loading training need:", error);
      }
    },

    async submitReview() {
      // Check if already reviewed
      if (this.isAlreadyReviewed && !this.canEdit) {
        this.showSnackbar("This request has already been reviewed", "error");
        return;
      }

      // Validate form
      this.$refs.form.validate();
      if (!this.valid) {
        this.showSnackbar("Please fill all required fields", "warning");
        return;
      }

      // Show confirmation dialog
      this.confirmDialogTitle = "Confirm Review Submission";
      this.confirmDialogMessage =
        "Are you sure you want to submit this review?";
      this.confirmDialogIcon = { icon: "mdi-send-check", color: "primary" };

      this.confirmDialog = true;
    },

    async confirmSubmit() {
      this.confirmDialog = false;
      this.submitting = true;
      this.overlay = true;

      try {
        // Process the review using mixin
        await this.processFHIR();

        this.showSnackbar("Review submitted successfully!", "success");
        this.editReview = false;
        await this.getReviews();
        await this.loadRequestData();
      } catch (error) {
        console.log(error);
        console.error("Error submitting review:", error);
        this.showSnackbar("Error submitting review", "error");
      } finally {
        this.submitting = false;
        this.overlay = false;
      }
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/my-tasks");
      }
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    getTrainingTypeColor(type) {
      const colors = {
        long: "indigo",
        short: "teal",
        parttime: "purple",
      };
      return colors[type] || "grey";
    },

    getStatusColor(status) {
      const colors = {
        undersupervisorreview: "orange",
        underhodreview: "deep-purple",
        underhrreview: "blue",
        underpsreview: "purple",
        approved: "green",
        rejected: "red",
        pending: "grey",
      };
      return colors[status] || "grey";
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },
  },

  async created() {
    this.reviewDate = new Date().toISOString().split("T")[0];

    await this.$nextTick();

    // Wait for generalMixin to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    await this.checkAccess();

    if (!this.isPS) {
      this.loadingRequest = false;
      return;
    }

    this.getReviews();
    this.loadRequestData();
  },

  components: {
    "fhir-choice": () => import("@/components/fhir/fhir-choice"),
    "fhir-string": () => import("@/components/fhir/fhir-string"),
    "fhir-date": () => import("@/components/fhir/fhir-date"),
    "ihris-questionnaire-section": () =>
      import("@/components/ihris/ihris-questionnaire-section"),
  },
};
</script>

